/* ChartPulse — Shared Design System */
:root {
  --bg-primary: #0f0f0f;
  --bg-secondary: #161616;
  --bg-tertiary: #1e1e1e;
  --bg-card: #1a1a1a;
  --bg-hover: #252525;
  --border: #2a2a2a;
  --border-light: #333;
  --accent-blue: #2962ff;
  --accent-blue-hover: #1a4fd8;
  --accent-teal: #00bcd4;
  --gain: #26a69a;
  --gain-bright: #4caf50;
  --loss: #ef5350;
  --loss-bright: #f44336;
  --text-primary: #e8e8e8;
  --text-secondary: #9e9e9e;
  --text-muted: #666;
  --text-dim: #444;
  --gold: #ffd700;
  --platinum: #b0bec5;
  --font: 'Inter', 'DM Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --radius-sm: 4px;
  --radius: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font);
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: 13px;
  line-height: 1.5;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
button { cursor: pointer; border: none; background: none; font-family: var(--font); }

/* ── Scrollbar ── */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-primary); }
::-webkit-scrollbar-thumb { background: var(--border-light); border-radius: 3px; }

/* ── NAV ── */
.nav {
  display: flex;
  align-items: center;
  height: 52px;
  padding: 0 20px;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 100;
  gap: 0;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 17px;
  font-weight: 700;
  color: var(--text-primary);
  margin-right: 32px;
  flex-shrink: 0;
}

.nav-logo svg { flex-shrink: 0; }

.nav-links {
  display: flex;
  align-items: center;
  gap: 2px;
  flex: 1;
}

.nav-link {
  padding: 6px 12px;
  font-size: 13px;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  transition: color 0.15s, background 0.15s;
  white-space: nowrap;
}

.nav-link:hover { color: var(--text-primary); background: var(--bg-hover); }
.nav-link.active { color: var(--text-primary); }

.nav-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
  flex-shrink: 0;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 16px;
  font-size: 13px;
  font-weight: 500;
  border-radius: var(--radius-sm);
  transition: all 0.15s;
  cursor: pointer;
}

.btn-ghost {
  color: var(--text-secondary);
  background: transparent;
  border: 1px solid transparent;
}
.btn-ghost:hover { color: var(--text-primary); background: var(--bg-hover); }

.btn-primary {
  background: var(--accent-blue);
  color: #fff;
  border: 1px solid var(--accent-blue);
}
.btn-primary:hover { background: var(--accent-blue-hover); }

.btn-outline {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border-light);
}
.btn-outline:hover { border-color: var(--accent-blue); color: var(--accent-blue); }

/* ── Market Ticker Bar ── */
.ticker-bar {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  overflow: hidden;
  padding: 0;
}

.ticker-scroll {
  display: flex;
  align-items: center;
  gap: 0;
  overflow-x: auto;
  scrollbar-width: none;
  padding: 0 16px;
}
.ticker-scroll::-webkit-scrollbar { display: none; }

.ticker-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  border-right: 1px solid var(--border);
  white-space: nowrap;
  flex-shrink: 0;
}

.ticker-name { color: var(--text-secondary); font-size: 12px; }
.ticker-price { font-size: 12px; font-weight: 600; }
.ticker-change { font-size: 11px; font-weight: 500; }
.gain { color: var(--gain); }
.loss { color: var(--loss); }
.neutral { color: var(--text-secondary); }

/* ── Tabs ── */
.tab-bar {
  display: flex;
  align-items: center;
  gap: 2px;
  border-bottom: 1px solid var(--border);
  padding: 0 4px;
}

.tab-btn {
  padding: 10px 16px;
  font-size: 13px;
  color: var(--text-secondary);
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  transition: all 0.15s;
  white-space: nowrap;
}

.tab-btn:hover { color: var(--text-primary); }
.tab-btn.active { color: var(--text-primary); border-bottom-color: var(--accent-blue); }

/* ── Cards ── */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 16px;
}

.card-sm { padding: 12px; }

/* ── Badge ── */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 7px;
  border-radius: 3px;
  font-size: 11px;
  font-weight: 600;
}
.badge-gain { background: rgba(38,166,154,0.15); color: var(--gain); }
.badge-loss { background: rgba(239,83,80,0.15); color: var(--loss); }
.badge-neutral { background: rgba(158,158,158,0.1); color: var(--text-secondary); }
.badge-blue { background: rgba(41,98,255,0.15); color: var(--accent-blue); }

/* ── Section ── */
.section { padding: 32px 24px; }
.section-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px; }
.section-title { font-size: 16px; font-weight: 600; color: var(--text-primary); }
.section-link { font-size: 12px; color: var(--accent-blue); }
.section-link:hover { text-decoration: underline; }

/* ── Tables ── */
.data-table {
  width: 100%;
  border-collapse: collapse;
}
.data-table th {
  text-align: left;
  font-size: 11px;
  font-weight: 500;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border);
}
.data-table td {
  padding: 10px 12px;
  font-size: 13px;
  border-bottom: 1px solid var(--border);
  color: var(--text-primary);
}
.data-table tr:hover td { background: var(--bg-hover); }
.data-table tr:last-child td { border-bottom: none; }
.data-table td.right, .data-table th.right { text-align: right; }

/* ── Sparkline ── */
.sparkline { display: inline-block; vertical-align: middle; }

/* ── Footer ── */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border);
  padding: 48px 24px 24px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 32px;
  max-width: 1280px;
  margin: 0 auto 40px;
}

.footer-col h4 {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.8px;
  margin-bottom: 12px;
}

.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 8px; }
.footer-col a { font-size: 13px; color: var(--text-muted); transition: color 0.15s; }
.footer-col a:hover { color: var(--text-primary); }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 24px;
  border-top: 1px solid var(--border);
  max-width: 1280px;
  margin: 0 auto;
}

.footer-logo { font-size: 15px; font-weight: 700; }
.footer-copy { font-size: 12px; color: var(--text-muted); }

/* ── Utility ── */
.flex { display: flex; }
.flex-col { display: flex; flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.gap-4 { gap: 4px; }
.gap-8 { gap: 8px; }
.gap-12 { gap: 12px; }
.gap-16 { gap: 16px; }
.gap-24 { gap: 24px; }
.w-full { width: 100%; }
.truncate { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.text-sm { font-size: 12px; }
.text-xs { font-size: 11px; }
.text-muted { color: var(--text-muted); }
.text-secondary { color: var(--text-secondary); }
.font-mono { font-family: 'JetBrains Mono', 'Courier New', monospace; }
.font-bold { font-weight: 600; }
.text-right { text-align: right; }
.hidden { display: none !important; }

/* ── Rating Stars ── */
.rating { display: inline-flex; align-items: center; gap: 4px; font-size: 12px; }
.stars { color: var(--gold); }

/* ── Spinner / pulse ── */
@keyframes pulse { 0%,100% { opacity: 1; } 50% { opacity: 0.4; } }
.live-dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--gain);
  animation: pulse 2s infinite;
  display: inline-block;
}

/* ── Responsive ── */
@media (max-width: 1024px) {
  .nav-links .nav-link:nth-child(n+5) { display: none; }
}

@media (max-width: 768px) {
  .section { padding: 20px 16px; }
  .nav { padding: 0 12px; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

