  user-select: none; transition: background 0.1s;
}
.wl-cat-header:hover { background: var(--bg-hover); }

.wl-cat-name {
  font-size: 11px; font-weight: 600; text-transform: uppercase;
  letter-spacing: 0.6px; color: var(--text-muted);
}

.wl-cat-toggle { color: var(--text-muted); font-size: 10px; transition: transform 0.2s; }
.wl-cat-toggle.open { transform: rotate(90deg); }

.wl-cat-body { overflow: hidden; }
.wl-cat-body.collapsed { display: none; }

.wl-row {
  display: grid; grid-template-columns: 1fr auto auto;
  gap: 4px; padding: 7px 12px; cursor: pointer;
  align-items: center; transition: background 0.1s;
  border-bottom: 1px solid rgba(255,255,255,0.03);
}
.wl-row:hover { background: var(--bg-hover); }
.wl-row.active { background: rgba(41,98,255,0.08); }

.wl-symbol { font-size: 12px; font-weight: 600; }
.wl-price { font-size: 12px; text-align: right; }
.wl-chg { font-size: 11px; text-align: right; font-weight: 500; }

/* ── Main Chart Area ── */
.chart-main {
  flex: 1; display: flex; flex-direction: column; overflow: hidden;
  background: var(--bg-primary);
}

/* Toolbar */
.chart-toolbar {
  display: flex; align-items: center; gap: 4px;
  padding: 6px 12px; background: var(--bg-secondary);
  border-bottom: 1px solid var(--border); flex-shrink: 0;
  flex-wrap: nowrap; overflow-x: auto;
}
.chart-toolbar::-webkit-scrollbar { display: none; }

.toolbar-sep { width: 1px; height: 20px; background: var(--border-light); margin: 0 4px; flex-shrink: 0; }

.tool-btn {
  display: inline-flex; align-items: center; justify-content: center;
  width: 32px; height: 28px; border-radius: var(--radius-sm);
  color: var(--text-secondary); font-size: 13px; flex-shrink: 0;
  transition: background 0.1s, color 0.1s;
}
.tool-btn:hover { background: var(--bg-hover); color: var(--text-primary); }
.tool-btn.active { background: var(--bg-hover); color: var(--accent-blue); }

.tf-btn {
  padding: 3px 8px; font-size: 12px; font-weight: 500;
  color: var(--text-secondary); border-radius: var(--radius-sm);
  transition: all 0.1s; flex-shrink: 0; cursor: pointer;
}
.tf-btn:hover { background: var(--bg-hover); color: var(--text-primary); }
.tf-btn.active { background: rgba(41,98,255,0.15); color: var(--accent-blue); }

.ticker-search-bar {
  display: flex; align-items: center; gap: 8px;
  padding: 4px 10px; background: var(--bg-tertiary);
  border: 1px solid var(--border); border-radius: var(--radius-sm);
  min-width: 160px;
}
.ticker-search-bar .sym { font-size: 14px; font-weight: 700; color: var(--text-primary); }
.ticker-search-bar .mkt { font-size: 11px; color: var(--text-muted); }

/* Chart canvas area */
.chart-canvas-area {
  flex: 1; position: relative; overflow: hidden;
  background: var(--bg-primary);
}

.chart-price-header {
  position: absolute; top: 12px; left: 12px; z-index: 5;
}

.chart-symbol { font-size: 16px; font-weight: 700; }
.chart-price-big { font-size: 24px; font-weight: 700; margin: 2px 0; }
.chart-ohlcv { font-size: 11px; color: var(--text-muted); display: flex; gap: 12px; margin-top: 2px; }

/* Timeframe buttons row */
.timeframe-bar {
  position: absolute; top: 12px; right: 12px;
  display: flex; gap: 2px; z-index: 5;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 2px;
}

.time-btn {
  padding: 3px 8px; font-size: 11px; font-weight: 500;
  color: var(--text-muted); border-radius: 3px;
  cursor: pointer; transition: all 0.1s;
}
.time-btn:hover { color: var(--text-primary); }
.time-btn.active { background: var(--accent-blue); color: #fff; }

/* SVG candlestick chart */
.chart-svg { width: 100%; height: 100%; }

/* Y-axis price labels */
.y-axis {
  position: absolute; right: 0; top: 0; bottom: 0;
  width: 72px; border-left: 1px solid var(--border);
  background: var(--bg-secondary);
  display: flex; flex-direction: column; justify-content: space-around;
  padding: 80px 8px 20px; pointer-events: none;
}
.y-label { font-size: 11px; color: var(--text-muted); text-align: right; font-family: 'Courier New', monospace; }

/* X-axis */
.x-axis {
  height: 24px; background: var(--bg-secondary);
  border-top: 1px solid var(--border);
  flex-shrink: 0; display: flex; align-items: center;
  padding: 0 80px 0 12px;
}
.x-labels { display: flex; justify-content: space-around; width: 100%; }
.x-label { font-size: 10px; color: var(--text-muted); }

/* ── Right Panel ── */
.detail-panel {
  width: 280px; flex-shrink: 0;
  background: var(--bg-secondary);
  border-left: 1px solid var(--border);
  overflow-y: auto; display: flex; flex-direction: column;
}

.detail-stock-header {
  padding: 16px; border-bottom: 1px solid var(--border);
}

.detail-sym { font-size: 11px; color: var(--text-muted); }
.detail-company { font-size: 15px; font-weight: 700; margin: 4px 0 2px; }
.detail-exchange { font-size: 11px; color: var(--text-muted); }
.detail-price { font-size: 28px; font-weight: 800; margin: 10px 0 4px; }
.detail-change { font-size: 14px; font-weight: 600; }

.detail-premarket {
  margin-top: 10px; padding: 8px 10px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  font-size: 12px;
}
.detail-premarket-val { font-size: 14px; font-weight: 600; color: var(--gain); }

.stat-row {
  display: flex; justify-content: space-between; align-items: center;
  padding: 8px 16px; border-bottom: 1px solid rgba(255,255,255,0.04);
}
.stat-label { font-size: 12px; color: var(--text-muted); }
.stat-value { font-size: 12px; font-weight: 600; text-align: right; }

.news-item {
  padding: 12px 16px; border-bottom: 1px solid var(--border);
  font-size: 12px; line-height: 1.5; color: var(--text-secondary);
  cursor: pointer; transition: background 0.1s;
}
.news-item:hover { background: var(--bg-hover); }

.detail-section-title {
  font-size: 11px; font-weight: 600; text-transform: uppercase;
  letter-spacing: 0.6px; color: var(--text-muted);
  padding: 12px 16px 6px;
}

.financials-tab-bar {
  display: flex; border-bottom: 1px solid var(--border); padding: 0 8px;
}
.fin-tab {
  padding: 8px 10px; font-size: 12px; color: var(--text-muted);
  border-bottom: 2px solid transparent; margin-bottom: -1px;
  cursor: pointer; transition: all 0.1s;
}
.fin-tab:hover { color: var(--text-primary); }
.fin-tab.active { color: var(--text-primary); border-bottom-color: var(--accent-blue); }

/* Analyst rating pill */
.rating-pill {
  display: inline-flex; align-items: center; gap: 6px;
