}
.rating-neutral { background: rgba(158,158,158,0.15); color: var(--text-secondary); }

/* Performance bars */
.perf-bar-bg { height: 4px; background: var(--border-light); border-radius: 2px; flex: 1; overflow: hidden; }
.perf-bar-fill { height: 100%; border-radius: 2px; }
