<script>
const allCards = () => document.querySelectorAll('.broker-card');

function filterBrokers(btn, cat) {
  document.querySelectorAll('#catTabs .filter-tab').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  allCards().forEach(card => {
    const cats = card.dataset.cats || '';
    if (cat === 'all' || cats.includes(cat)) {
      card.style.display = '';
    } else {
      card.style.display = 'none';
    }
  });
}

function sortBrokers(btn, mode) {
  document.querySelectorAll('.sort-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  const container = document.querySelector('.brokers-content');
  const cards = [...allCards()];
  if (mode === 'best') {
    cards.sort((a, b) => parseFloat(b.dataset.rating) - parseFloat(a.dataset.rating));
  } else {
    cards.sort(() => 0);
  }
  cards.forEach(c => container.appendChild(c));
}
</script>
